const tabId = 725789690;
const pageHtml = await browserjs(tabId, () => {
  const html = document.documentElement.outerHTML;
  // Let's find occurrences of 8KUFV
  const matches = [];
  let idx = 0;
  while ((idx = html.indexOf('8KUFV', idx)) !== -1) {
    matches.push(html.substring(Math.max(0, idx - 100), Math.min(html.length, idx + 200)));
    idx += 5;
    if (matches.length > 20) break;
  }
  return matches;
});
console.log("Matches:", JSON.stringify(pageHtml, null, 2));

