const tabId = 725789690;
const colorAnalysis = await browserjs(tabId, () => {
  const img = document.querySelector('img[src*="8KUFV"]');
  if (!img) return null;
  const canvas = document.createElement('canvas');
  canvas.width = 50;
  canvas.height = 50;
  const ctx = canvas.getContext('2d');
  try {
    ctx.drawImage(img, 0, 0, 50, 50);
    const data = ctx.getImageData(25, 25, 1, 1).data;
    return { r: data[0], g: data[1], b: data[2] };
  } catch (e) {
    return { error: e.message };
  }
});
console.log("Color analysis:", colorAnalysis);

