const tabId = 725789701;
const adidasInfo = await browserjs(tabId, () => {
  const title = document.querySelector('h1')?.innerText;
  const price = document.querySelector('[data-auto-id="gl-price"], [class*="gl-price"]')?.innerText;
  const sizes = Array.from(document.querySelectorAll('button[data-auto-id*="size"], [class*="size-selector"] button, button')).filter(b => b.innerText?.trim() === '12' || b.innerText?.trim().startsWith('12')).map(b => ({
    text: b.innerText?.trim(),
    disabled: b.disabled || b.getAttribute('aria-disabled') === 'true' || b.className.includes('disabled') || b.className.includes('out-of-stock')
  }));
  const fullText = document.body.innerText;
  const priceMatch = fullText.match(/\$\d+(\.\d{2})?/g);
  return { title, price, sizes, priceMatch: priceMatch?.slice(0, 10) };
});
console.log("adidas.com info:", JSON.stringify(adidasInfo, null, 2));

